-- 每日一言：全站按 UTC+8 日历日固定一句，90天不重新选用。所有删除都是状态标记。
-- 内置内容是公版原文摘句，作者/篇名/链接逐条核对；目录副本见 src/data/daily-quote-classics.json。
CREATE TABLE IF NOT EXISTS "daily_quotes" (
  "id" TEXT NOT NULL PRIMARY KEY, "kind" TEXT NOT NULL, "content" TEXT NOT NULL,
  "content_key" TEXT NOT NULL, "category" TEXT NOT NULL, "signature" TEXT NOT NULL DEFAULT 'nickname',
  "source_type" TEXT NOT NULL, "source_name" TEXT, "source_url" TEXT, "author_name" TEXT,
  "submitter_id" TEXT, "status" TEXT NOT NULL DEFAULT 'pending', "review_reason" TEXT,
  "reviewer_id" TEXT, "created_at" DATETIME NOT NULL, "reviewed_at" DATETIME,
  FOREIGN KEY ("submitter_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE,
  FOREIGN KEY ("reviewer_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "daily_quotes_content_key_key" ON "daily_quotes"("content_key");
CREATE INDEX IF NOT EXISTS "ix_daily_quotes_pool" ON "daily_quotes"("kind", "status");
CREATE INDEX IF NOT EXISTS "ix_daily_quotes_submitter" ON "daily_quotes"("submitter_id", "created_at");
CREATE TABLE IF NOT EXISTS "daily_quote_editions" (
  "day" TEXT NOT NULL PRIMARY KEY, "quote_id" TEXT NOT NULL, "created_at" DATETIME NOT NULL,
  FOREIGN KEY ("quote_id") REFERENCES "daily_quotes"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS "ix_daily_quote_editions_quote" ON "daily_quote_editions"("quote_id");
CREATE TABLE IF NOT EXISTS "daily_quote_resonances" (
  "quote_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "day" TEXT NOT NULL,
  "paid_units" INTEGER NOT NULL DEFAULT 0, "created_at" DATETIME NOT NULL,
  PRIMARY KEY ("quote_id", "user_id", "day"),
  FOREIGN KEY ("quote_id") REFERENCES "daily_quotes"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS "ix_daily_quote_resonances_user" ON "daily_quote_resonances"("user_id");
CREATE TABLE IF NOT EXISTS "daily_quote_favorites" (
  "user_id" TEXT NOT NULL, "quote_id" TEXT NOT NULL, "created_at" DATETIME NOT NULL,
  "deleted" BOOLEAN NOT NULL DEFAULT false, "deleted_at" DATETIME,
  PRIMARY KEY ("user_id", "quote_id"),
  FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  FOREIGN KEY ("quote_id") REFERENCES "daily_quotes"("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX IF NOT EXISTS "ix_daily_quote_favorites_quote" ON "daily_quote_favorites"("quote_id");

-- 固定的 UTC+8 墙上时间毫秒，与仓库 DateTime 存储约定一致。仅初次插入，不覆盖已有审核状态。
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-001','builtin','学而时习之，不亦说乎？','4960641b12d46e7b3755b78209708bcd67472be16b2ed97578e315b23f8b3f3d','励志','quotation','《论语》','https://zh.wikisource.org/zh-hans/%E8%AB%96%E8%AA%9E/%E5%85%A8%E8%A6%BD','孔子','approved',1792540800000);
