INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-157','builtin','生于忧患而死于安乐也。','91aeca86cf789cf71724a8ba0e711ec024c5ec3336034434cce1b5b6704209b0','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-158','builtin','行有不得者，皆反求诸己。','70110f6d16a8abf2ef4d702c37e601e1994181075618dbb19272ae05ae16de1c','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-159','builtin','不挟长，不挟贵，不挟兄弟而友。','bec8b4df9ef92a9415a08d3249825c17051cd067196f261a5571697aa8b410e0','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-160','builtin','诚者，天之道也；思诚者，人之道也。','bb81da08e48dd6b7f3311174d5026571c8cf9e4d013b67f074288108650390a2','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
