INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-162','builtin','声闻过情，君子耻之。','a0ee5e27161b78e06d7ce771c49992c9752918a6452e99f9d55dfc9537c1cedb','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
