INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-164','builtin','养心莫善于寡欲。','b4e7bf50add553eb1ef9c20dc902aad10053d63cad91c57b8ef1f1a0c0cc78aa','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-165','builtin','大人者，不失其赤子之心者也。','638bb04f4dbf15593e4a5c600f9962c08e9308848eaee0d79939ca02cc024db4','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-166','builtin','得天下英才而教育之，三乐也。','e0d9d86dd4ac09ab25e78fbc76f6a35cd500f11147ad6303347e95147c33e42c','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-167','builtin','君子之守，修其身而天下平。','8e3e3ff5ac941d64f8ed821eb8bad7150ea9db5acb9569df8bf5bff9fef4fe48','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
