INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-171','builtin','彼一时，此一时也。','090e210f9a5ed98f4b891e2791deccbfe838837711df9948b13ffba9c768b2e1','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-172','builtin','我善养吾浩然之气。','e47269e38ce998b5cb18b186bbb5be60e424b5a92bfc4cab6ac874ae0e0bb9ed','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-173','builtin','仁之实，事亲是也；义之实，从兄是也。','4b4a437e14bac465fda13659fa3b8f8a28f0234c465c95f0ce6e5d2175780a82','哲思','quotation','《孟子》','https://zh.wikisource.org/zh-hans/%E5%AD%9F%E5%AD%90/%E5%85%A8%E8%A6%BD','孟子','approved',1792540800000);
