INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-181','builtin','学不可以已。','6b1b4094b89351de67f654e69baa72972a31037efb68720f04e9a6795a644ea8','励志','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-182','builtin','青，取之于蓝，而青于蓝。','d7e533a802e9e57cff9059e1c071e151d944efc27d62a02d5eb5b6fe30ef94fd','励志','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-183','builtin','冰，水为之，而寒于水。','cfbaab51e8ab82b1f668ed0d7aeed6ce25553b5596bd6d8f596a9ca49d02db31','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-184','builtin','木受绳则直，金就砺则利。','426490dfc7d64e053434b008fe4fa303b369f0c378f6f70120a4d23d35783f4c','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-185','builtin','君子博学而日参省乎己，则知明而行无过矣。','c38e76cad6f10fdcf7f2cea8e5ae7da7cbafc7c5a7af6ec5c952fa7914da76a7','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-186','builtin','不登高山，不知天之高也。','8acda1cd761219216fc12ec33ab3547702eb2907db1de1ca013730d9e4bc53c7','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-187','builtin','不临深谿，不知地之厚也。','2db594cd1adca8a2c5331006df595156d1c432beca7c6cda1d40e7b217f8082b','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-188','builtin','吾尝终日而思矣，不如须臾之所学也。','b3081ebc04e273f7a11bd28e5536de6700127357774305303d47126a4b3f3d8b','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-189','builtin','登高而招，臂非加长也，而见者远。','b6a3fca6bbff76c55fc512d8a991c734aac21d7da7d1a7f4bb435a6f3ac31fc8','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-190','builtin','君子生非异也，善假于物也。','5ed16fa43a2255102de7d676c2405e773c322c229baa5dd55a004be939c7c40d','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-191','builtin','积土成山，风雨兴焉；积水成渊，蛟龙生焉。','4a4e2298165487aa7a3203a8067c36b8bb7ac1e5d5afd61e5cc18f9d1940187a','励志','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-192','builtin','不积跬步，无以至千里；不积小流，无以成江海。','264b79c12a7c80b4716f9a9c4f6e3557f33754abc2221de787894bf0717a3a7e','励志','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-193','builtin','骐骥一跃，不能十步；驽马十驾，功在不舍。','159ebde74e1b0d44567a040a80f4fd4cff91410f3a6d2b6933eed9cb43add2c2','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-194','builtin','锲而舍之，朽木不折；锲而不舍，金石可镂。','f73e6252e5b96a54dcae2c7cf6d62257af72a6300427028a04f76d9018094433','励志','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-195','builtin','蓬生麻中，不扶而直。','b7efd3407b194890b4e9fad420019670795b08cd2a0e7b7baafe67017c2d4b81','哲思','quotation','《荀子·劝学》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E5%8B%B8%E5%AD%B8%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-196','builtin','道虽迩，不行不至；事虽小，不为不成。','6f143abd0a9f5ac90961b0ba3f3a174b0ea54a21d48b8ee828cc3e095a8b8969','哲思','quotation','《荀子·修身》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E4%BF%AE%E8%BA%AB%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-197','builtin','人无礼则不生，事无礼则不成，国家无礼则不宁。','59f92f7cf383418cf86c5c98818fa7523a4f311ac2f22793205077d0625934c6','哲思','quotation','《荀子·修身》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E4%BF%AE%E8%BA%AB%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-198','builtin','以善先人者谓之教，以善和人者谓之顺。','96a458d259461849dfd4f455a9a2a770f5982ba5ecf4c63304f47ea7eb2b3658','哲思','quotation','《荀子·修身》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E4%BF%AE%E8%BA%AB%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-199','builtin','非我而当者，吾师也；是我而当者，吾友也。','684dd14712f048b78ace8c4559496ef8f85e8c6bda2a99a8b29ea0eeea8e1c2e','哲思','quotation','《荀子·修身》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E4%BF%AE%E8%BA%AB%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-200','builtin','谄谀我者，吾贼也。','6b6c96ebc67139c2c5c68fc8f234e2dbfbaa5651983aed28a4e25e51dd771276','哲思','quotation','《荀子·修身》','https://zh.wikisource.org/zh-hans/%E8%8D%80%E5%AD%90/%E4%BF%AE%E8%BA%AB%E7%AF%87','荀子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-201','builtin','水之积也不厚，则负大舟也无力。','d1613ac6baceccae08385482920fd4dddcb9a0862fb5d4c5f93fc54a08678c3d','哲思','quotation','《庄子·逍遥游》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-202','builtin','小知不及大知，小年不及大年。','3c5717685cda50f07533b22b37cfb69fd4f50c95d6979a3fcff16ff567438961','哲思','quotation','《庄子·逍遥游》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-203','builtin','朝菌不知晦朔，蟪蛄不知春秋。','2b06d34a8bf7b4437f94f5e87a54d9e037829cb9c1d4ad26f20a5ac613c34c29','哲思','quotation','《庄子·逍遥游》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-204','builtin','举世而誉之而不加劝，举世而非之而不加沮。','42f5f4cc214594375ea790ae4d62680909a3d1c33d9c7651f28974547717b171','哲思','quotation','《庄子·逍遥游》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-205','builtin','至人无己，神人无功，圣人无名。','44f9b5463d05ec4a78d43fe63a9085cb872386ed13bbeff3cf92c8d167d28b0b','哲思','quotation','《庄子·逍遥游》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-206','builtin','名者，实之宾也。','f4157b774972e6870c353d644a9d7318a49bc47651979d8de72244e0910a2b4b','哲思','quotation','《庄子·逍遥游》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%80%8D%E9%81%99%E9%81%8A','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-207','builtin','吾生也有涯，而知也无涯。','074dc3b10f622d21137889dd546203f0d860b9b32b5e84417e5233f600a1e2d0','哲思','quotation','《庄子·养生主》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%A4%8A%E7%94%9F%E4%B8%BB','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-208','builtin','为善无近名，为恶无近刑。','088c2997cf6a2a0c2aa28c47303d889f385657aa0f963bead89ede924e4c3dd2','哲思','quotation','《庄子·养生主》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%A4%8A%E7%94%9F%E4%B8%BB','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-209','builtin','指穷于为薪，火传也，不知其尽也。','f05b19d12b00864c1fa47038c145086fd8deb80b179bd11536df73e40963f005','哲思','quotation','《庄子·养生主》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E9%A4%8A%E7%94%9F%E4%B8%BB','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-210','builtin','知其不可奈何而安之若命，德之至也。','c73c0ebc5136d8f31f986eb3139537956dda9d1d6cde3461a6b91503a10aa69d','哲思','quotation','《庄子·人间世》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E4%BA%BA%E9%96%93%E4%B8%96','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-211','builtin','人皆知有用之用，而莫知无用之用也。','ef8902832322842fd8654d07141d8c0785834e6649603d03074d1c103345bab5','哲思','quotation','《庄子·人间世》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E4%BA%BA%E9%96%93%E4%B8%96','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-212','builtin','相濡以沫，不如相忘于江湖。','6cb1e9ccfde0a32912541efce02f46a8ce985c89f73ef44724ca5f29a4aa9542','哲思','quotation','《庄子·大宗师》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E5%A4%A7%E5%AE%97%E5%B8%AB','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-213','builtin','泉涸，鱼相与处于陆，相呴以湿，相濡以沫。','af9ab37cf59c27251b75f33b1962d67ff19effb2ec828f4dbac1e63275212817','哲思','quotation','《庄子·大宗师》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E5%A4%A7%E5%AE%97%E5%B8%AB','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-214','builtin','井蛙不可以语于海者，拘于墟也。','0b36635358917c1aef738f667ea8d1894adc01bf9fbbb88620534c4d581c54d1','哲思','quotation','《庄子·秋水》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E7%A7%8B%E6%B0%B4','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-215','builtin','夏虫不可以语于冰者，笃于时也。','b4ce6931be238d3aa713fb98025576c5cb25251a1d25cf0b16634fea8536d7e9','哲思','quotation','《庄子·秋水》','https://zh.wikisource.org/zh-hans/%E8%8E%8A%E5%AD%90/%E7%A7%8B%E6%B0%B4','庄子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-216','builtin','志不彊者智不达，言不信者行不果。','fc050aaaf559052b935764ca2664b83e4ac23e13747369624988b68db597269e','哲思','quotation','《墨子·修身》','https://zh.wikisource.org/zh-hans/%E5%A2%A8%E5%AD%90/%E4%BF%AE%E8%BA%AB','墨子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-217','builtin','名不徒生，而誉不自长。','ea50fa87f39df6d54c3a7c3de89cfdbad80095e967ea10d0ff17667e2d1a551f','哲思','quotation','《墨子·修身》','https://zh.wikisource.org/zh-hans/%E5%A2%A8%E5%AD%90/%E4%BF%AE%E8%BA%AB','墨子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-218','builtin','言无务为多而务为智，无务为文而务为察。','0ad770cb344058a56fde48b0269da9f19c31820bb968d06d806bfc1f29d3c303','哲思','quotation','《墨子·修身》','https://zh.wikisource.org/zh-hans/%E5%A2%A8%E5%AD%90/%E4%BF%AE%E8%BA%AB','墨子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-219','builtin','士虽有学，而行为本焉。','ec3f53305c5969a15bf1ce849b1cb08a4652f499836da5121f97d2115124defa','哲思','quotation','《墨子·修身》','https://zh.wikisource.org/zh-hans/%E5%A2%A8%E5%AD%90/%E4%BF%AE%E8%BA%AB','墨子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-220','builtin','名不可简而成也，誉不可巧而立也。','bf733a8784c7caab54c40099883d084c568b83312d62f189dc5acc3c47dc5ddd','哲思','quotation','《墨子·修身》','https://zh.wikisource.org/zh-hans/%E5%A2%A8%E5%AD%90/%E4%BF%AE%E8%BA%AB','墨子','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-221','builtin','千丈之堤，以蝼蚁之穴溃。','39c04530bbfb625105d9ce4b0eec79f59c6490ff403f2b424df44580e614658f','哲思','quotation','《韩非子·喻老》','https://zh.wikisource.org/zh-hans/%E9%9F%93%E9%9D%9E%E5%AD%90/%E5%96%BB%E8%80%81','韩非','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-222','builtin','有形之类，大必起于小；行久之物，族必起于少。','ff518ffb4526a437a7c469bdfe6ed4017ce37151f9f6e3a7d822031528dc23be','哲思','quotation','《韩非子·喻老》','https://zh.wikisource.org/zh-hans/%E9%9F%93%E9%9D%9E%E5%AD%90/%E5%96%BB%E8%80%81','韩非','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-223','builtin','此皆慎易以避难，敬细以远大者也。','4be6ff4beec3e10b157dd171947267c3cb9568af0236451e3f225925867e41fd','哲思','quotation','《韩非子·喻老》','https://zh.wikisource.org/zh-hans/%E9%9F%93%E9%9D%9E%E5%AD%90/%E5%96%BB%E8%80%81','韩非','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-224','builtin','知之难，不在见人，在自见。','07960f4be0bddcb8e03760ccdab13fbc4559932ff4bb7bb2144003acce731e9b','哲思','quotation','《韩非子·喻老》','https://zh.wikisource.org/zh-hans/%E9%9F%93%E9%9D%9E%E5%AD%90/%E5%96%BB%E8%80%81','韩非','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-225','builtin','志之难也，不在胜人，在自胜也。','7a30d778fd510f2466b15671307991f7a926b810ee7c84f5f93dc72786c27ba2','哲思','quotation','《韩非子·喻老》','https://zh.wikisource.org/zh-hans/%E9%9F%93%E9%9D%9E%E5%AD%90/%E5%96%BB%E8%80%81','韩非','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-226','builtin','玉不琢，不成器。人不学，不知道。','07701308952eeb6e39608290c5d6aefa93c78d4810719ce54572441c509e26c2','哲思','quotation','《礼记·学记》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%AD%B8%E8%A8%98','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-227','builtin','学然后知不足，教然后知困。','f4271baa78fd2c708ff426077b03c030e9a2b52e783eeff3e9a9fb5f6992a6e5','哲思','quotation','《礼记·学记》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%AD%B8%E8%A8%98','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-228','builtin','独学而无友，则孤陋而寡闻。','46f5353c7f9b65c3cf77528a2fc643c36d4fe3ea1add358f9bb929485a37d22f','哲思','quotation','《礼记·学记》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%AD%B8%E8%A8%98','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-229','builtin','道而弗牵，强而弗抑，开而弗达。','269dacbd99b56bd4e89c91c9c95c51007adf87d4ffc51d792860c1b607656286','哲思','quotation','《礼记·学记》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%AD%B8%E8%A8%98','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-230','builtin','善歌者使人继其声，善教者使人继其志。','6e9b1cb47e52da253064c7a73fd060b182d094cd3490ce4b719a63fd41050aa8','哲思','quotation','《礼记·学记》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%AD%B8%E8%A8%98','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-231','builtin','教也者，长善而救其失者也。','a0b6d51d084864e01cfb808307ba858f9b91dd0179357eda6a54003013331432','哲思','quotation','《礼记·学记》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%AD%B8%E8%A8%98','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-232','builtin','大学之道，在明明德，在亲民，在止于至善。','c40a1dc22210a53563ec67f3eee796ce5930f03f7e8f93cdcef2994f72cf0c0f','哲思','quotation','《礼记·大学》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%A4%A7%E5%AD%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-233','builtin','物有本末，事有终始，知所先后，则近道矣。','914b4f0639896ca6a9ba249ec8696c66c2c12fe81761e41cf9692114df7374fd','哲思','quotation','《礼记·大学》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%A4%A7%E5%AD%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-234','builtin','苟日新，日日新，又日新。','e38b25c94e686098b6eb284f825253661ca4483513f06d347da8f6e18199dab6','哲思','quotation','《礼记·大学》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%A4%A7%E5%AD%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-235','builtin','富润屋，德润身。','7ce634c750ed16aaf3e97d72e44699e8bdefde93170be71748f6cef79f73f209','哲思','quotation','《礼记·大学》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E5%A4%A7%E5%AD%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-236','builtin','博学之，审问之，慎思之，明辨之，笃行之。','75aaf34df50895b3c870c4504e1b1af363cb524f8ccbaddd3e595b136b775bc0','哲思','quotation','《礼记·中庸》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E4%B8%AD%E5%BA%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-237','builtin','好学近乎知，力行近乎仁，知耻近乎勇。','21e058358d4f547b52a6541efb08ebfce7ce550d1e840815c5f07b6925bc60e6','哲思','quotation','《礼记·中庸》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E4%B8%AD%E5%BA%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-238','builtin','凡事豫则立，不豫则废。','1a47f1e161cc4b04825c493a7f8d6f528cd6740883f83c3469fd69d948981a78','哲思','quotation','《礼记·中庸》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E4%B8%AD%E5%BA%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-239','builtin','人一能之，己百之；人十能之，己千之。','70a5d7c72375ae6b047cf4304ac0bf9240e1a5232d0dd5544fd5b666682914be','哲思','quotation','《礼记·中庸》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E4%B8%AD%E5%BA%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-240','builtin','君子慎其独也。','5b8ceaa0b984bc7a4ae6843ab3a8777f798750c50e969d05bf30af8f066f418a','哲思','quotation','《礼记·中庸》','https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E4%B8%AD%E5%BA%B8','《礼记》','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-241','builtin','交友须带三分侠气，做人要存一点素心。','96fc05f4dad7641a355650d37d5b447f4ff4b275c0fa89efc0fc7a8e36523071','治愈','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-242','builtin','径路窄处，留一步与人行；滋味浓的，减三分让人嗜。','d93ff247ce9e5236ec1515280441b891790886f2d63e83873b19a17d673c3260','治愈','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-243','builtin','闲时要有吃紧的心思，忙处要有悠闲的趣味。','bae72f6cbfa551f16867b23e70dc8e664d230bbf85c406ca5ce7ef8134a4b1eb','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-244','builtin','败后或反成功，故拂心处，莫便放手。','a21f71d489390cac2c53ae37a8e1a68ec40913984b7bdb2ac82023089ad4ae79','励志','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-245','builtin','处世让一步为高，退步即进步的张本。','8b99f5b6107009d5cbe5057e5ce48decd20f17a1555ba50a318b4b1847b6bc00','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-246','builtin','待人宽一分是福，利人实利己的根基。','5480efaa1a20ce1e9b31fc97a1d98900d157b33636105a8e73913b95c1873df7','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-247','builtin','事事留个有馀不尽的意思。','705fb32696ca862ed70e6bebe38a4a77d2daae6c2ab7fa97c5b72be55d53371e','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-248','builtin','攻人之恶，毋太严，要思其堪受。','c4ce7f03dd313ae1af32cd9ffb2cfedd23fe12c0231c3f8da2b64a12f4c967db','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-249','builtin','教人之善，毋过高，当使其可从。','196674c176a10d34213136d4894857ce309e8f816080fd8637ccf316ba46e2c2','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-250','builtin','处世不必邀功，无过便是功。','5ca28d0cead559f5150107eecbd2776e5fcac5b2dc9cadc44c1bad65c617f305','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-251','builtin','与人不求感德，无怨便是德。','818d506bf89b8d9bcfe85235039ef343860321b567935b2fa592fcac563f325a','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-252','builtin','福莫福于少事，祸莫祸于多心。','a030c7db55569ab12bd0a8ad8ee17d75ff143db0b9e0aa7afd445eb0fa27e092','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-253','builtin','我有功于人不可念，而过则不可不念。','47b397be5e1d78187f71704ddaf27c34d53877f03431dc12163f4b16ee18c5b2','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
