INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-255','builtin','苦心中，常得悦心之趣。','f715c594a5a5d18d000a5da6662d3b6c7ca78dc31db852291f3e28f35fa932c0','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-256','builtin','得意时，须防失意之悲。','c69feb0a1468dcf3b477aced367a8e796f564ddf958063151152ed2b5479a394','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-257','builtin','风恬浪静中，见人生之真境。','2bd643988a18922fa760f67bf722043773422bd3359916fefe70e3d64b7879b8','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-258','builtin','味淡声希处，识心体之本然。','a7cb1e20b1430cfbcac4a132244c17d98246251807503f15a57260df6ad39b74','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-259','builtin','真廉无廉名，图名者正所以为贪。','8775fed89e05ca10f99ddc80baf389eff9b83c05e26ba89f3048145622a9fcda','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-260','builtin','大巧无巧术，用术者乃所以为拙。','674be4ebad60b89bdb9a28aca7780920a3794a001767f6aae468a26b30c8958e','哲思','quotation','《菜根谭》','https://zh.wikisource.org/zh-hans/%E8%8F%9C%E6%A0%B9%E8%AD%9A','洪应明','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-261','builtin','人有悲欢离合，月有阴晴圆缺，此事古难全。','b6ec3ea24093f3f82865d7c8a99a0274b5b77e52831fea445268e46c584a093c','治愈','quotation','《水调歌头》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-262','builtin','但愿人长久，千里共婵娟。','24f8331f0cabcd94ddb970a6cc48208abd503ec2cb98b53dc0bc1a00976b294e','治愈','quotation','《水调歌头》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-263','builtin','莫听穿林打叶声，何妨吟啸且徐行。','bed68e4e563e524ea57a697dce5acf00fffc03576e5a0912fd117ea2d775359d','励志','quotation','《定风波》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-264','builtin','竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。','466d371abf21400d0a3ffb3cfd0ff7f65a8019187559b5622352f5c659be27a5','励志','quotation','《定风波》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-265','builtin','回首向来萧瑟处，归去，也无风雨也无晴。','310c7a5f8f0cff3cad5e3af82d2e69196615ae509fdf0acb50050724b1144a75','治愈','quotation','《定风波》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-266','builtin','小舟从此逝，江海寄馀生。','06a4fafba7b215d45c9f18458df75da7c818f583eed59618bee1f3725e962eaf','治愈','quotation','《临江仙》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-267','builtin','春色三分，二分尘土，一分流水。','2c3871ce006142001faa762a027d725f8d55272f5398858511af0882d64a2d10','哲思','quotation','《水龙吟》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-268','builtin','明月如霜，好风如水，清景无限。','0b2ac1128fb1e19024ea159937c376ac7c1e80c58e9e378c23ee8a0c48138e4e','治愈','quotation','《永遇乐》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-269','builtin','古今如梦，何曾梦觉，但有旧欢新怨。','3d3775c0fa63be38cfb3b315ea0ab1b6f2b2dca9e426fb62108e587ea6de78b9','哲思','quotation','《永遇乐》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-270','builtin','长恨此身非我有，何时忘却营营。','3f484ee291261784e346e9428cec0c9d115e8b9ff9ec6e860619f33e6a4dcfd4','哲思','quotation','《临江仙》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','苏轼','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-271','builtin','衣带渐宽终不悔，为伊消得人憔悴。','35addfb12dda7bad7dc46950a2195a450a8c16bba171a9ce1f3c7c02ed4d0030','扎心','quotation','《蝶恋花》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','柳永','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-272','builtin','多情自古伤离别，更那堪、冷落清秋节。','22c8b0fc19b5cfdc3b4a7f931c92343f5eab1bccf98b57ab3230b1893c6331d8','扎心','quotation','《雨霖铃》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','柳永','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-273','builtin','今宵酒醒何处？杨柳岸、晓风残月。','ac44e12147814d4897f60e13a60b37a7125ec02fdbdfe86e16fa408f46dd5303','扎心','quotation','《雨霖铃》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','柳永','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-274','builtin','便纵有、千种风情，更与何人说？','0ded397184d5be4d488c28ac78551711926b7f0a51c61be08e6bbfa77960611c','扎心','quotation','《雨霖铃》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','柳永','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-275','builtin','无可奈何花落去，似曾相识燕归来。','83d33cbf03e99db8abbc887f22708c0b2a4cd73f4fe25db0a6d571f136f9b163','扎心','quotation','《浣溪沙》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','晏殊','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-276','builtin','昨夜西风凋碧树，独上高楼，望尽天涯路。','dc5c9b132f2ca087144504c6338d50bb1221e76b95df3776453be431521fb106','扎心','quotation','《蝶恋花》','https://zh.wikisource.org/zh-hans/%E8%9D%B6%E6%88%80%E8%8A%B1%20%28%E6%99%8F%E6%AE%8A%29','晏殊','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-277','builtin','满目山河空念远，落花风雨更伤春，不如怜取眼前人。','3d4022b65dc1d3c556558d44f8bb828f4940fb366346ad482ecb2fc77da42227','治愈','quotation','《浣溪沙》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','晏殊','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-278','builtin','欲寄彩笺兼尺素，山长水阔知何处？','5c7e72b92cae3aecadeea002dddf133e37b1c25ed659921a49305f6d25527372','扎心','quotation','《蝶恋花》','https://zh.wikisource.org/zh-hans/%E8%9D%B6%E6%88%80%E8%8A%B1%20%28%E6%99%8F%E6%AE%8A%29','晏殊','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-279','builtin','泪眼问花花不语，乱红飞过秋千去。','d2a3953aece64f30178d9c5b07a51a08343898a5ccd77e55a7493f3629f35689','扎心','quotation','《蝶恋花》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','欧阳修','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-280','builtin','人生自是有情痴，此恨不关风与月。','ebe6cdeff23f64640851e1bee82a240369510befb1c83305d7865821889b05ee','治愈','quotation','《玉楼春》','https://zh.wikisource.org/zh-hans/%E7%8E%89%E6%A8%93%E6%98%A5%20%28%E6%AD%90%E9%99%BD%E4%BF%AE%29','欧阳修','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-281','builtin','离愁渐远渐无穷，迢迢不断如春水。','2576193f426900ff5c1e6e2e0eb8371a01f37a052ee67c8549db1b08177f1d69','扎心','quotation','《踏莎行》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','欧阳修','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-282','builtin','直须看尽洛阳花，始共春风容易别。','5987d3cf90df182dd589373bc685047f70280ba6ccc54239e93ebca2684daa08','治愈','quotation','《玉楼春》','https://zh.wikisource.org/zh-hans/%E7%8E%89%E6%A8%93%E6%98%A5%20%28%E6%AD%90%E9%99%BD%E4%BF%AE%29','欧阳修','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-283','builtin','莫道不销魂，帘卷西风，人比黄花瘦。','43078179bb73500722ea48e5a62204d933cf48ed724307f5d2edf29cc4af2aa5','扎心','quotation','《醉花阴》','https://zh.wikisource.org/zh-hans/%E9%86%89%E8%8A%B1%E9%99%B0%20%28%E6%9D%8E%E6%B8%85%E7%85%A7%29','李清照','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-284','builtin','此情无计可消除，才下眉头，却上心头。','eb7cc7a2c90575571511c772a8925fabad6698b4c8df757f0a9d56cbb2bc8c41','扎心','quotation','《一剪梅》','https://zh.wikisource.org/zh-hans/%E4%B8%80%E5%89%AA%E6%A2%85%20%28%E6%9D%8E%E6%B8%85%E7%85%A7%29','李清照','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-285','builtin','物是人非事事休，欲语泪先流。','edd0ca850b6f1d29250283cd105942f55990079458e39cefb04d089df8c97bc7','扎心','quotation','《武陵春》','https://zh.wikisource.org/zh-hans/%E6%AD%A6%E9%99%B5%E6%98%A5%20%28%E6%9D%8E%E6%B8%85%E7%85%A7%29','李清照','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-286','builtin','想当年，金戈铁马，气吞万里如虎。','ca07f700fa588ba52ad5ffab397a98d0b76649f80c5a0f02700e319e101f0369','励志','quotation','《永遇乐·京口北固亭怀古》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','辛弃疾','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-287','builtin','众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。','b068805358fb71def8c6848f3fd3512f1fe648c30b8e5bc754f12b0ef320a596','治愈','quotation','《青玉案》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','辛弃疾','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-288','builtin','而今识尽愁滋味，欲说还休。','407c0c2665df7be7d21a6f8bbd4cd9602e589068ebc3b05baf18f1ec629dec3b','扎心','quotation','《丑奴儿·书博山道中壁》','https://zh.wikisource.org/zh-hans/%E9%86%9C%E5%A5%B4%E5%85%92%C2%B7%E6%9B%B8%E5%8D%9A%E5%B1%B1%E9%81%93%E4%B8%AD%E5%A3%81','辛弃疾','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-289','builtin','青山遮不住，毕竟江流去。','1798727300b21f425f94787ea8e821b0cd885c54ce0e89c22322a9985b9d21ee','励志','quotation','《菩萨蛮》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','辛弃疾','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-290','builtin','千古江山，英雄无觅、孙仲谋处。','69577b6ce8fe2891a5d4270c4255fce6176b8c70e85e24f84432c59a88b2e032','扎心','quotation','《永遇乐·京口北固亭怀古》','https://zh.wikisource.org/zh-hans/%E5%AE%8B%E8%A9%9E%E4%B8%89%E7%99%BE%E9%A6%96','辛弃疾','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-291','builtin','天生我材必有用，千金散尽还复来。','b04396ddd506f8f56772c8b4590f288cda06a4c3b7ae11271bc53cfa9b39bd34','励志','quotation','《将进酒》','https://zh.wikisource.org/zh-hans/%E5%B0%87%E9%80%B2%E9%85%92%20%28%E6%9D%8E%E7%99%BD%29','李白','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-292','builtin','人生得意须尽欢，莫使金樽空对月。','5f3fd9bce714edb9f5647df9d28eefe1b11c208b370682e62cbdd06f7e9a8788','治愈','quotation','《将进酒》','https://zh.wikisource.org/zh-hans/%E5%B0%87%E9%80%B2%E9%85%92%20%28%E6%9D%8E%E7%99%BD%29','李白','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-293','builtin','长风破浪会有时，直挂云帆济沧海。','2b4f23629335c2979ace63c3a3775d48fc1c5ca3029ae11e7618c536d25798cb','励志','quotation','《行路难》','https://zh.wikisource.org/zh-hans/%E8%A1%8C%E8%B7%AF%E9%9B%A3%20%28%E6%9D%8E%E7%99%BD%29','李白','approved',1792540800000);
INSERT OR IGNORE INTO daily_quotes (id,kind,content,content_key,category,source_type,source_name,source_url,author_name,status,created_at) VALUES ('builtin-294','builtin','大道如青天，我独不得出。','3089cf92801925e427df4d2052458bb23ade8e1942f2597d121235a30ae05927','励志','quotation','《行路难》','https://zh.wikisource.org/zh-hans/%E8%A1%8C%E8%B7%AF%E9%9B%A3%20%28%E6%9D%8E%E7%99%BD%29','李白','approved',1792540800000);
